functions.show_opcode:
void show_opcode(Instruction *instruction, int instr_count)
{
    printf("bytecode:\n");
    for (int i = 0; i < instr_count; i++)
    {
        if (instruction[i].operand)
        {
            printf("%-15s \t (%s)\n", get_opcode_name(instruction[i].opcode), instruction[i].operand);
        }
        else
        {
            printf("%-15s \t *\n", get_opcode_name(instruction[i].opcode));
        }
    }
    printf("\n");
}

functions.show_tokens:
void show_tokens(Token *tokens)
{
    printf("tokens:\n");
    for (int i = 0; tokens[i].type != TOKEN_EOF; i++)
    {
        printf("%-15s \t (%s)\n", get_token_type_name(tokens[i].type), tokens[i].value);
    }
    printf("\n");
}

functions.print_ast:
void print_ast(ASTNode *node, int level)
{
    if (!node)
        return;
    for (int i = 0; i < level; i++)
    {
        printf("  ");
    }
    switch (node->type)
    {
    case TOKEN_INT:
        printf("INT: %s\n", node->value);
        break;
    case TOKEN_IDENTIFIER:
        printf("IDENTIFIER: %s\n", node->value);
        break;
    case TOKEN_ASSIGN:
        printf("ASSIGN: %s\n", node->value);
        break;
    case TOKEN_LET:
        printf("LET: %s\n", node->value);
        break;
    case TOKEN_PLUS:
        printf("PLUS\n");
        break;
    case TOKEN_MINUS:
        printf("MINUS\n");
        break;
    case TOKEN_DIS:
        printf("DISPLAY\n");
        break;
    default:
        printf("UNKNOWN\n");
        break;
    }
    if (node->left)
    {
        print_ast(node->left, level + 1);
    }
    if (node->right)
    {
        print_ast(node->right, level + 1);
    }
}

functions.print_asts:
void print_asts(ASTNode **asts)
{
    printf("AST:\n");
    for (int i = 0; asts[i] != ((void *)0); i++)
    {
        print_ast(asts[i], 0);
        printf("\n");
    }
    printf("\n");
}

functions.read_file:
char *read_file(const char *source_path)
{
    struct dirent *entry;
    char *source = (char *)malloc(sizeof(char) * 2000);
    FILE *file = fopen(source_path, "r");
    if (file == ((void *)0))
    {
        perror("Could not open file");
        exit(-1);
    }
    int pos = 0;
    char ch;
    while ((ch = fgetc(file)) != (-1))
    {
        memcpy(&source[pos], &ch, sizeof(char));
        pos++;
    }
    source[pos] = '\0';
    fclose(file);
    return source;
}

