functions.tokenize:
Token *tokenize(const char *source)
{
    Token *tokens = (Token *)malloc(sizeof(Token) * 200);
    int pos = 0;
    int len = strlen(source);
    int index = 0;
    while (pos < len)
    {
        if (((*__ctype_b_loc())[(int)((source[pos]))] & (unsigned short int)_ISspace))
        {
            pos++;
        }
        else if (((*__ctype_b_loc())[(int)((source[pos]))] & (unsigned short int)_ISdigit))
        {
            int start = pos;
            while (((*__ctype_b_loc())[(int)((source[pos]))] & (unsigned short int)_ISdigit))
            {
                pos++;
            }
            char *num = strndup(&source[start], pos - start);
            tokens[index] = *new_token(TOKEN_INT, num);
            index++;
            free(num);
        }
        else if (((*__ctype_b_loc())[(int)((source[pos]))] & (unsigned short int)_ISalpha))
        {
            int start = pos;
            while (((*__ctype_b_loc())[(int)((source[pos]))] & (unsigned short int)_ISalpha))
            {
                pos++;
            }
            char *indent = strndup(&source[start], pos - start);
            if (strcmp(indent, "let") == 0)
            {
                tokens[index] = *new_token(TOKEN_LET, indent);
                index++;
            }
            else if (strcmp(indent, "dis") == 0)
            {
                tokens[index] = *new_token(TOKEN_DIS, indent);
                index++;
            }
            else
            {
                tokens[index] = *new_token(TOKEN_IDENTIFIER, indent);
                index++;
            }
            free(indent);
        }
        else
        {
            switch (source[pos])
            {
            case '+':
                tokens[index] = *new_token(TOKEN_PLUS, "+");
                index++;
                break;
            case '-':
                tokens[index] = *new_token(TOKEN_MINUS, "-");
                index++;
                break;
            case ';':
                tokens[index] = *new_token(TOKEN_SEMICOLON, ";");
                index++;
                break;
            case '=':
                tokens[index] = *new_token(TOKEN_ASSIGN, "=");
                index++;
                break;
            default:
                fprintf(stderr, "SyntaxError: unexpected character %c\n", source[pos]);
                exit(1);
            }
            pos++;
        }
    }
    tokens[index] = *new_token(TOKEN_EOF, "");
    return tokens;
}

